	// Check if data is empty? Still unknown
	return nil, fmt.Sprintf("Error: can't decode %s: image: unknown format\n\n", name)
}

func isBMPData(data []byte) bool {
	return len(data) >= 2 && data[0] == 'B' && data[1] == 'M'
}

