	fs.BoolVarP(&flagFlipY, "flipY", "y", false, "")
	fs.StringVarP(&flagSaveImg, "save-img", "s", "", "")
	fs.StringVar(&flagSaveTxt, "save-txt", "", "")
	fs.StringVar(&flagSaveGif, "save-gif", "", "")
	fs.IntSliceVar(&flagSaveBg, "save-bg", nil, "")
	fs.StringVar(&flagFont, "font", "", "")
	fs.IntSliceVar(&flagFontColor, "font-color", nil, "")
	fs.BoolVar(&flagOnlySave, "only-save", false, "")
	fs.BoolVar(&flagFormats, "formats", false, "")
	fs.BoolVarP(&flagHelp, "help", "h", false, "")
	fs.BoolVarP(&flagVersion, "version", "v", false, "")

	err := fs.Parse(os.Args[1:])
	if err != nil {
		msg := err.Error()
		printUsageError(msg)
		os.Exit(1)
	}

	if flagHelp {
		fmt.Fprint(os.Stdout, helpText)
		os.Exit(0)
	}
	if flagVersion {
		fmt.Fprint(os.Stdout, versionStr)
		os.Exit(0)
	}
	if flagFormats {
		fmt.Fprint(os.Stdout, formatsStr)
		os.Exit(0)
	}

	args := fs.Args()
	if len(args) == 0 {
		fmt.Fprint(os.Stdout, "Error: Need at least 1 input path/url or piped input\nUse the -h flag for more info\n\n")
		os.Exit(0)
	}

	if fs.Changed("dimensions") {
		if len(flagDimensions) != 2 {
			fmt.Fprintf(os.Stdout, "Error: requires 2 dimensions, got %d\n\n", len(flagDimensions))
			os.Exit(0)
		}
		if flagDimensions[0] <= 0 || flagDimensions[1] <= 0 {
			fmt.Fprint(os.Stdout, "Error: invalid values for dimensions\n\n")
			os.Exit(0)
		}
	}
	if fs.Changed("width") {
		if flagWidth < 0 {
			fmt.Fprint(os.Stdout, "Error: invalid value for width\n\n")
			os.Exit(0)
		}
