	if fs.Changed("font-color") {
		if len(flagFontColor) != 3 {
			fmt.Fprintf(os.Stdout, "Error: --font-color requires 3 values for RGB, got %d\n\n", len(flagFontColor))
			os.Exit(0)
		}
	}
	if fs.Changed("save-bg") {
		invalidRGB := false
		for i := 0; i < 3; i++ {
			if flagSaveBg[i] < 0 || flagSaveBg[i] > 255 {
				invalidRGB = true
				break
			}
		}
		invalidA := flagSaveBg[3] < 0 || flagSaveBg[3] > 100
		if invalidRGB || invalidA {
			fmt.Fprint(os.Stdout, "Error: RBG values must be between 0 and 255\nError: Opacity value must be between 0 and 100\n\n")
