		if len([]rune(flagMap)) == 1 {
			fmt.Fprint(os.Stdout, "Error: Need at least 2 characters for --map flag\n\n")
			os.Exit(0)
		}
	}
	if fs.Changed("threshold") {
		if flagThreshold < 0 || flagThreshold > 255 {
