	saveBg := []int{0, 0, 0, 100}
	if fs.Changed("save-bg") {
		saveBg = flagSaveBg
	}
	fontColor := []int{255, 255, 255}
	if fs.Changed("font-color") {
		fontColor = flagFontColor
	}

	if (flagSaveImg != "" || flagSaveGif != "") && flagFont != "" {
		if _, err := os.Stat(flagFont); err != nil {
			fmt.Fprintf(os.Stdout, "Error: unable to open font file: open %s: no such file or directory\n\n", flagFont)
			os.Exit(0)
		}
	}

	opts := convertOpts{
		color:      flagColor,
		colorBg:    flagColorBg,
		dimensions: flagDimensions,
		hasDims:    fs.Changed("dimensions"),
		width:      flagWidth,
