		saveBg:     saveBg,
		font:       flagFont,
		fontColor:  fontColor,
		hasFontColor: fs.Changed("font-color"),
		onlySave:   flagOnlySave,
	}

	// Process each input
	for _, input := range args {
		processInput(input, opts, fs)
	}
}

