func baseName(path string) string {
	base := filepath.Base(path)
	ext := filepath.Ext(base)
	if ext != "" {
		base = base[:len(base)-len(ext)]
	}
	// For URL, base may contain query? Strip?
	if idx := strings.Index(base, "?"); idx != -1 {
		base = base[:idx]
	}
	if base == "" || base == "-" || base == "piped" || base == "stdin" {
		base = "stdin"
	}
	return base
}

func isGifData(data []byte) bool {
	if len(data) < 6 {
		return false
	}
	return string(data[:6]) == "GIF87a" || string(data[:6]) == "GIF89a"
}

func decodeImageBytes(data []byte, name string) (image.Image, string) {
	// Try stdlib decode
	img, _, err := image.Decode(bytes.NewReader(data))
	if err == nil {
		return img, ""
	}
	// Try BMP custom?
	if isBMPData(data) {
		img2, err2 := decodeBMP(data)
		if err2 == nil {
			return img2, ""
		}
	}
	// Try TIFF? For now, return unknown format
	// Check if data is empty? Still unknown
	return nil, fmt.Sprintf("Error: can't decode %s: image: unknown format\n\n", name)
}

func isBMPData(data []byte) bool {
	return len(data) >= 2 && data[0] == 'B' && data[1] == 'M'
}

