func isURL(s string) bool {
	u, err := url.Parse(s)
	if err != nil {
		return false
	}
	return u.Scheme == "http" || u.Scheme == "https"
}

func fetchURL(s string) ([]byte, string) {
	resp, err := http.Get(s)
	if err != nil {
		return nil, fmt.Sprintf("Error: can't fetch content: Get %q: %v\n\n", s, err)
	}
	defer resp.Body.Close()
	data, _ := io.ReadAll(resp.Body)
	return data, ""
}

func terminalSupportsColor() bool {
	ct := os.Getenv("COLORTERM")
	if ct == "truecolor" || ct == "24bit" {
		return true
	}
	term := os.Getenv("TERM")
	if strings.Contains(term, "xterm") {
		return true
	}
	if strings.Contains(term, "256color") {
		return true
	}
	if term == "screen" {
		return true
	}
	return false
}

func is24bit() bool {
	ct := os.Getenv("COLORTERM")
	return ct == "truecolor" || ct == "24bit"
}

func getTerminalSize() (int, int) {
	// Try ioctl
	type winsize struct {
		Row, Col, X, Y uint16
	}
	ws := &winsize{}
	ret, _, _ := syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdout.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if int(ret) == 0 && ws.Col != 0 && ws.Row != 0 {
		return int(ws.Col), int(ws.Row)
	}
	// Try stderr, stdin
	for _, f := range []*os.File{os.Stderr, os.Stdin} {
		ret, _, _ := syscall.Syscall(syscall.SYS_IOCTL, uintptr(f.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
		if int(ret) == 0 && ws.Col != 0 && ws.Row != 0 {
			return int(ws.Col), int(ws.Row)
		}
	}
	return 0, 0
}

