		// What about extreme like (47,47,47) already returned 0, so not here. Good.
		return val
	}
	// Otherwise cube
	level := func(v int) int {
		if v < 48 {
			return 0
		} else if v < 115 {
			return 1
		} else if v < 155 {
			return 2
		} else if v < 195 {
			return 3
		} else if v < 235 {
			return 4
		} else {
			return 5
		}
	}
	return 16 + 36*level(ri) + 6*level(gi) + level(bi)
