import subprocess, os, re
def get_colors(path, dims, exe):
    env=os.environ.copy(); env['TERM']='xterm'; env['COLORTERM']='truecolor'
    out=subprocess.run([exe,path,'-d',dims,'-C'], capture_output=True, env=env).stdout.decode()
    m=re.findall(r'38;2;(\d+);', out)
